schema.content:
Table "Addresses" {
  "Address_ID" INTEGER [pk, not null]
  "address_details" TEXT
}

Table "Agreements" {
  "Document_ID" INTEGER [pk, not null]
  "Event_ID" INTEGER [not null]
}

Table "Assets" {
  "Asset_ID" INTEGER [pk, not null]
  "Other_Details" TEXT
}

Table "Assets_in_Events" {
  "Asset_ID" INTEGER [pk, not null]
  "Event_ID" INTEGER [pk, not null]
}

Table "Channels" {
  "Channel_ID" INTEGER [pk, not null]
  "Other_Details" TEXT
}

Table "Events" {
  "Event_ID" INTEGER [pk, not null]
  "Address_ID" INTEGER
  "Channel_ID" INTEGER [not null]
  "Event_Type_Code" TEXT
  "Finance_ID" INTEGER [not null]
  "Location_ID" INTEGER [not null]
}

Table "Finances" {
  "Finance_ID" INTEGER [pk, not null]
  "Other_Details" TEXT
}

Table "Locations" {
  "Location_ID" INTEGER [pk, not null]
  "Other_Details" TEXT
}

Table "Parties" {
  "Party_ID" INTEGER [pk, not null]
  "Party_Details" TEXT
}

Table "Parties_in_Events" {
  "Party_ID" INTEGER [pk, not null]
  "Event_ID" INTEGER [pk, not null]
  "Role_Code" TEXT
}

Table "Products" {
  "Product_ID" INTEGER [pk, not null]
  "Product_Type_Code" TEXT
  "Product_Name" TEXT
  "Product_Price" TEXT
}

Table "Products_in_Events" {
  "Product_in_Event_ID" INTEGER [pk, not null]
  "Event_ID" INTEGER [not null]
  "Product_ID" INTEGER [not null]
}



Ref: "Events"."Finance_ID" > "Finances"."Finance_ID"

Ref: "Events"."Address_ID" > "Addresses"."Address_ID"

Ref: "Events"."Location_ID" > "Locations"."Location_ID"

Ref: "Products_in_Events"."Product_ID" > "Products"."Product_ID"

Ref: "Products_in_Events"."Event_ID" > "Events"."Event_ID"

Ref: "Parties_in_Events"."Event_ID" > "Events"."Event_ID"

Ref: "Parties_in_Events"."Party_ID" > "Parties"."Party_ID"

Ref: "Agreements"."Event_ID" > "Events"."Event_ID"

Ref: "Assets_in_Events"."Event_ID" > "Events"."Event_ID"

